CREATE TABLE r (
    id VARCHAR PRIMARY KEY
);

CREATE TABLE ca (
    id VARCHAR PRIMARY KEY,
    rid VARCHAR NOT NULL,
    a INTEGER NOT NULL
);

CREATE TABLE cb (
    id VARCHAR PRIMARY KEY,
    rid VARCHAR NOT NULL,
    b BOOLEAN NOT NULL
);

CREATE TABLE cc (
    id VARCHAR PRIMARY KEY,
    rid VARCHAR NOT NULL,
    c TIMESTAMP(9) WITH TIME ZONE NOT NULL
);
